contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner) public payable {
        require(true);
        // observe owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // perform the call and record if it reverted and the returned value
        bool didRevert;
        bool retVal;
        bool ok = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
            retVal = false;
        } else {
            didRevert = false;
            retVal = ok;
        }

        // observe owner after
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General invariant:
        // - If the call reverted, owner must be unchanged.
        // - If the call did not revert, it must have returned true and owner must equal newOwner,
        //   and it can only succeed when this contract was the pre-call owner.
        assert((didRevert && ownerAfter == ownerBefore) || (!didRevert && retVal == true && ownerAfter == newOwner && ownerBefore == address(this)));
    }
    receive() external payable {}
}

